# ── DECODIFICA E SALVA ───────────────────────────────────────
try {
    Write-Host "  Decodifica file Excel..." -ForegroundColor Yellow -NoNewline
    $Bytes = [System.Convert]::FromBase64String($Base64.Trim())
    Write-Host " OK (877 kB)" -ForegroundColor Green

    Write-Host "  Salvataggio su Desktop..." -ForegroundColor Yellow -NoNewline
    [System.IO.File]::WriteAllBytes($OutputPath, $Bytes)
    Write-Host " OK" -ForegroundColor Green

    Write-Host ""
    Write-Host "  FILE CREATO:" -ForegroundColor Cyan
    Write-Host "  $OutputPath" -ForegroundColor White
    Write-Host ""

    $Apri = Read-Host "  Apri il file adesso? [S/N]"
    if ($Apri -match "^[Ss]") {
        Write-Host "  Apertura in corso..." -ForegroundColor Yellow
        Start-Process $OutputPath
    }
}
catch {
    Write-Host ""
    Write-Host "  ERRORE: $($_.Exception.Message)" -ForegroundColor Red
}

Write-Host ""
Write-Host "  Premi INVIO per chiudere..." -ForegroundColor DarkGray
Read-Host | Out-Null